@functools.partial(jax.vmap, in_axes=(1, 1, None), out_axes=1)
def _exponent_convolve(data: jnp.ndarray, exponent: jnp.ndarray) -> jnp.ndarray:
  """Applies the convolution between the data and the weights for the exponent.

  Args:
    data: Input data.
    exponent: Window weights for the exponent.

  Returns:
    The result values from convolving the data and the weights with padding.
  """
  window = jnp.concatenate([jnp.zeros(1), exponent])
  return jax.scipy.signal.convolve(data, window, mode="same") / exponent.sum()


